BirthInfoVerifier.verify.source:
verify(submitted: KycBirthInfoDto, document: BirthPlace | null): BirthInfoVerification {
  if (!document) return { ok: true, enforced: [], mismatches: [] };
  const enforced = FIELDS.filter((f) => document[f]);
  const mismatches = enforced
    .filter((f) => normalize(submitted[f]) !== normalize(document[f]!))
    .map((f) => ({ field: f, submitted: submitted[f], document: document[f]! }));
  return { ok: mismatches.length === 0, enforced, mismatches };
}

BirthInfoService.get.source:
async get(userId: string): Promise<BirthInfoView> {
  const [document, kyc] = await Promise.all([this.documents.forUser(userId), this.kyc.find(userId)]);
  return {
    userId,
    document,
    kyc: kyc ? { countryOfBirth: kyc.countryOfBirth, placeOfBirth: kyc.placeOfBirth, updatedAt: kyc.updatedAt } : null,
  };
}

BirthInfoService.updateKycBirthInfo.source:
async updateKycBirthInfo(userId: string, dto: KycBirthInfoDto): Promise<BirthInfoView> {
  const submitted = { countryOfBirth: dto.countryOfBirth.trim().toUpperCase(), placeOfBirth: dto.placeOfBirth.trim() };
  const document = await this.documents.forUser(userId);
  const check = this.verifier.verify(submitted, document);
  if (!check.ok) {
    throw new UnprocessableEntityException({ message: 'Birth info does not match the identity document', mismatches: check.mismatches });
  }
  // The new answer and its event go together: if either fails, neither happens.
  await this.dataSource.transaction(async (manager) => {
    await this.kyc.save(userId, submitted, manager);
    this.events.emit('kyc.birth_info.updated', { userId });
  });
  return this.get(userId);
}

KycBirthInfoStore.find.source:
async find(userId: string): Promise<KycBirthInfo | null> {
  return this.rows.findOneBy({ userId });
}

KycBirthInfoStore.save.source:
async save(userId: string, info: KycBirthInfoDto, manager?: EntityManager): Promise<KycBirthInfo> {
  const rows: Repository<KycBirthInfo> = manager ? manager.getRepository(KycBirthInfo) : this.rows;
  return rows.save({ userId, countryOfBirth: info.countryOfBirth, placeOfBirth: info.placeOfBirth, updatedAt: new Date().toISOString() });
}

DocumentBirthInfoService.forUser.source:
async forUser(userId: string): Promise<BirthPlace | null> {
  const row = await this.extracted.findOneBy({ userId });
  if (!row || (!row.countryOfBirth && !row.placeOfBirth)) return null;
  return {
    ...(row.countryOfBirth ? { countryOfBirth: row.countryOfBirth } : {}),
    ...(row.placeOfBirth ? { placeOfBirth: row.placeOfBirth } : {}),
  };
}

EligibilityService.check.source:
async check(userId: string): Promise<Eligibility> {
  const info = await this.birthInfo.get(userId);
  // The user's own (KYC) answer is the one we hold them to; the document is the fallback.
  const basedOn = info.kyc
    ? { source: 'kyc' as const, countryOfBirth: info.kyc.countryOfBirth, placeOfBirth: info.kyc.placeOfBirth }
    : info.document
      ? { source: 'document' as const, ...info.document }
      : { source: 'none' as const };
  const reasons: string[] = [];
  if (!basedOn.countryOfBirth) reasons.push('country of birth unknown');
  else if (this.policy.isRestricted(basedOn.countryOfBirth)) reasons.push(`country of birth ${basedOn.countryOfBirth} is restricted`);
  if (!basedOn.placeOfBirth) reasons.push('place of birth unknown');
  return { userId, eligible: reasons.length === 0, reasons, basedOn };
}
